int main(int argc,char**argv){std::string d="/data";for(int i=1;i+1<argc;++i)if(std::string(argv[i])=="--data-dir")d=argv[++i];try{lite::Engine e(d);std::cout<<"{\"type\":\"ready\"}\n"<<std::flush;std::string line;while(std::getline(std::cin,line)){lite::J req;try{req=lite::parse(line);bool shut=(req.o.count("type")&&req.o["type"].k==lite::J::S&&req.o["type"].s=="shutdown")||(req.o.count("op")&&req.o["op"].k==lite::J::S&&req.o["op"].s=="shutdown");if(shut){lite::J o=lite::jo();o.o["ok"]=lite::jb(true);if(req.o.count("id"))o.o["id"]=req.o["id"];std::cout<<lite::dump(o)<<"\n"<<std::flush;break;}if(!req.o.count("sql")||req.o["sql"].k!=lite::J::S)throw lite::Err("invalid_request","sql");lite::J out=e.exec(req.o["sql"].s);if(req.o.count("id"))out.o["id"]=req.o["id"];std::cout<<lite::dump(out)<<"\n"<<std::flush;}catch(const lite::Err&x){lite::J o=lite::jo();o.o["ok"]=lite::jb(false);lite::J er=lite::jo();er.o["code"]=lite::js(x.code);er.o["message"]=lite::js(x.what());o.o["error"]=er;if(req.k==lite::J::O&&req.o.count("id"))o.o["id"]=req.o["id"];std::cout<<lite::dump(o)<<"\n"<<std::flush;}catch(...){std::cout<<"{\"ok\":false,\"error\":{\"code\":\"invalid_request\",\"message\":\"failure\"}}\n"<<std::flush;}}}catch(const std::exception&x){std::cerr<<x.what()<<"\n";return 1;}}
